def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    points = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c]:
                points[grid[r][c]] = (r, c)

    def put(r, c, v):
        if 0 <= r < h and 0 <= c < w:
            out[r][c] = v

    # Each colored marker extends in its characteristic direction.
    for v, (r, c) in points.items():
        if v == 1:
            put(r, c + 1, 5)
            put(r, c + 2, 5)
            put(r - 1, c + 2, 1)
        elif v == 2:
            for x in range(c - 4, c + 1):
                put(r, x, 2 if x in (c - 4, c) else 5)
        elif v == 3:
            for y in range(r, r + 4):
                put(y, c, 3 if y in (r, r + 3) else 5)
        elif v == 6:
            for y in range(r - 6, r + 1):
                put(y, c, 6 if y in (r - 6, r) else 5)

    # Intersections between a horizontal 2-line and vertical 3/6-line
    # produce a 4 and a diagonal trail of 4s down-left.
    if 2 in points:
        r2, c2 = points[2]
        for v in (3, 6):
            if v not in points:
                continue
            rv, cv = points[v]
            if v == 3:
                vertical = range(rv, rv + 4)
            else:
                vertical = range(rv - 6, rv + 1)
            if r2 in vertical and c2 - 4 <= cv <= c2:
                put(r2, cv, 4)
                for k in range(1, h):
                    put(r2 + k, cv - k, 4)

    return out
